import { TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { RouterTestingModule } from '@angular/router/testing';
import { MessageService } from 'primeng/api';
import { vi } from 'vitest';
import AdminUserCreateLayoutPage from './admin-user-create-layout.page';
import { UserFormStateService } from './user-form-state.service';

describe('AdminUserCreateLayoutPage', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [AdminUserCreateLayoutPage, RouterTestingModule],
      providers: [MessageService, UserFormStateService],
    }).compileComponents();
  });

  it('Given the page is created, When initialized, Then component instance exists', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    expect(fixture.componentInstance).toBeTruthy();
  });

  it('Given the wizard steps, When steps are accessed, Then 5 steps are returned', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    expect(fixture.componentInstance.steps).toHaveLength(5);
  });

  it('Given a step with path "basic-information", When getStepRouterLink is called, Then returns correct admin URL', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const link = fixture.componentInstance.getStepRouterLink({
      label: 'Test',
      icon: 'pi-user',
      path: 'basic-information',
    });
    expect(link).toBe('/admin/utilisateurs/create/basic-information');
  });

  it('Given incomplete form state, When submit is attempted, Then sets error message', async () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance;

    await comp.handleSubmit();

    expect(comp['errorMessage']()).toBeTruthy();
  });

  it('Given invitation disabled, When submit is attempted, Then blocks submission with explicit message', async () => {
    const formState = TestBed.inject(UserFormStateService);
    formState.patch({
      firstName: 'Alice',
      lastName: 'Martin',
      email: 'alice@example.com',
      role: 'participant',
      sendInvitation: false,
    });
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance;

    await comp.handleSubmit();

    expect(comp['errorMessage']()).toContain('obligatoire');
  });

  it('Given a step matching current URL, When getStepButtonClass is called, Then active class is returned', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    vi.spyOn(comp.router, 'url', 'get').mockReturnValue(
      '/admin/utilisateurs/create/basic-information',
    );

    const css = comp.getStepButtonClass({
      label: 'Informations de base',
      icon: 'pi-user',
      path: 'basic-information',
    });

    expect(css).toContain('bg-brand-blue');
    expect(comp.currentStepIndex()).toBe(0);
  });

  it('Given a non-current step, When getStepButtonClass is called, Then inactive class is returned', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    vi.spyOn(comp.router, 'url', 'get').mockReturnValue(
      '/admin/utilisateurs/create/authorization',
    );

    const css = comp.getStepButtonClass({
      label: 'Localisation',
      icon: 'pi-map-marker',
      path: 'location-information',
    });

    expect(css).toContain('text-neutral-600');
    expect(comp.currentStepIndex()).toBe(3);
  });

  it('Given valid form data, When handleSubmit succeeds, Then invitation is sent, form is reset and navigation occurs', async () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    const formState = TestBed.inject(UserFormStateService);
    const messageService = TestBed.inject(MessageService);
    const router = TestBed.inject(Router);

    const addSpy = vi.spyOn(messageService, 'add');
    const navigateSpy = vi
      .spyOn(router, 'navigate')
      .mockResolvedValue(true as never);

    formState.patch({
      firstName: 'Alice',
      lastName: 'Martin',
      email: 'alice@example.com',
      role: 'participant',
      phone: '000',
      preferredContactChannel: 'email',
      isActive: true,
      sendInvitation: true,
    });

    comp.usersClient = {
      create: vi.fn().mockResolvedValue({ id: 'user-1' }),
    };

    await comp.handleSubmit();

    expect(comp.usersClient.create).toHaveBeenCalledWith({
      email: 'alice@example.com',
      firstName: 'Alice',
      lastName: 'Martin',
      role: 'participant',
      phone: '000',
      preferredContactChannel: 'email',
      isActive: true,
    });
    expect(addSpy).toHaveBeenCalled();
    expect(navigateSpy).toHaveBeenCalledWith(['/admin/utilisateurs/list']);
    expect(formState.state().firstName).toBe('');
    expect(comp.submitting()).toBe(false);
  });

  it('Given valid form data, When handleSubmit fails, Then error message is shown and submitting resets', async () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    const formState = TestBed.inject(UserFormStateService);

    formState.patch({
      firstName: 'Bob',
      lastName: 'Diallo',
      email: 'bob@example.com',
      role: 'admin',
      sendInvitation: true,
    });

    comp.usersClient = {
      create: vi.fn().mockRejectedValue(new Error('network')),
    };

    await comp.handleSubmit();

    expect(comp.errorMessage()).toContain("Impossible d'envoyer l'invitation");
    expect(comp.submitting()).toBe(false);
  });

  it('Given cancel action, When cancel is called, Then form resets and routes back to user list', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    const formState = TestBed.inject(UserFormStateService);
    const router = TestBed.inject(Router);
    const navigateSpy = vi
      .spyOn(router, 'navigate')
      .mockResolvedValue(true as never);

    formState.patch({
      firstName: 'Temp',
      email: 'temp@example.com',
      role: 'participant',
    });

    comp.cancel();

    expect(formState.state().firstName).toBe('');
    expect(navigateSpy).toHaveBeenCalledWith(['/admin/utilisateurs/list']);
  });

  it('Given form steps are invalid, When template is rendered, Then submit button is disabled', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    fixture.detectChanges();

    const submitButton = (fixture.nativeElement as HTMLElement).querySelector(
      'button.kr-button-primary',
    ) as HTMLButtonElement | null;

    expect(submitButton).toBeTruthy();
    expect(submitButton?.disabled).toBe(true);
  });

  it('Given form steps are valid and not submitting, When template is rendered, Then submit button is enabled', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    const formState = TestBed.inject(UserFormStateService);

    formState.patch({
      firstName: 'Alice',
      lastName: 'Martin',
      email: 'alice@example.com',
      role: 'participant',
      sendInvitation: true,
    });

    comp.submitting.set(false);
    fixture.detectChanges();

    const submitButton = (fixture.nativeElement as HTMLElement).querySelector(
      'button.kr-button-primary',
    ) as HTMLButtonElement | null;

    expect(submitButton).toBeTruthy();
    expect(submitButton?.disabled).toBe(false);
  });

  it('Given submitting state, When template is rendered, Then spinner is visible and submit button is disabled', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;
    const formState = TestBed.inject(UserFormStateService);

    formState.patch({
      firstName: 'Alice',
      lastName: 'Martin',
      email: 'alice@example.com',
      role: 'participant',
      sendInvitation: true,
    });

    comp.submitting.set(true);
    fixture.detectChanges();

    const host = fixture.nativeElement as HTMLElement;
    const submitButton = host.querySelector(
      'button.kr-button-primary',
    ) as HTMLButtonElement | null;
    const spinner = host.querySelector('.pi-spinner');

    expect(submitButton).toBeTruthy();
    expect(submitButton?.disabled).toBe(true);
    expect(spinner).toBeTruthy();
  });

  it('Given an explicit error message, When template is rendered, Then error feedback is visible', () => {
    const fixture = TestBed.createComponent(AdminUserCreateLayoutPage);
    const comp = fixture.componentInstance as any;

    comp.errorMessage.set('Erreur de soumission');
    fixture.detectChanges();

    expect((fixture.nativeElement as HTMLElement).textContent ?? '').toContain(
      'Erreur de soumission',
    );
  });
});

import { expect, test } from '@playwright/test';

// Analytics E2E — vérification du gating GA4
// Given/When/Then : sans identifiant GA4 configuré, aucun script GA n'est chargé.

const PUBLIC_CTA_SURFACES = [
  {
    path: '/',
    ctaLabel: 'Réserver une consultation',
  },
  {
    path: '/a-propos',
    ctaLabel: 'Nous contacter',
  },
  {
    path: '/services',
    ctaLabel: 'Réserver une consultation',
  },
  {
    path: '/ressources',
    ctaLabel: 'Demander une orientation',
  },
  {
    path: '/programmes',
    ctaLabel: 'Demander une orientation',
  },
  {
    path: '/mentions-legales',
    ctaLabel: 'Nous contacter',
  },
  {
    path: '/politique-de-confidentialite',
    ctaLabel: 'Nous contacter',
  },
] as const;

const PUBLIC_CTA_MATRIX_TIMEOUT_MS = 90000;

function isAnalyticsRequestUrl(url: string): boolean {
  return (
    url.includes('googletagmanager.com') || url.includes('google-analytics.com')
  );
}

test.describe('Analytics — gating GA4', () => {
  test(`Given aucun identifiant GA4 configuré, When la page d'accueil se charge, Then aucun loader gtag.js n'est injecté`, async ({
    page,
  }) => {
    await page.goto('/', { waitUntil: 'domcontentloaded' });
    await expect(page.getByRole('banner')).toBeVisible();

    await expect(
      page.locator('script[data-kraak-analytics="loader"]'),
    ).toHaveCount(0);
  });

  test(`Given aucun identifiant GA4 configuré, When la page d'accueil se charge, Then aucun appel à googletagmanager.com n'est émis`, async ({
    page,
  }) => {
    const gtagRequests: string[] = [];
    page.on('request', (request) => {
      const url = request.url();
      if (
        url.includes('googletagmanager.com') ||
        url.includes('google-analytics.com')
      ) {
        gtagRequests.push(url);
      }
    });

    await page.goto('/', { waitUntil: 'domcontentloaded' });
    await expect(page.getByRole('banner')).toBeVisible();

    expect(gtagRequests).toEqual([]);
  });

  test(`Given aucun identifiant GA4 configuré, When les pages publiques à CTA se chargent puis déclenchent leur CTA principal, Then aucun loader GA4 ni requête tierce n'est émis`, async ({
    page,
  }) => {
    test.setTimeout(PUBLIC_CTA_MATRIX_TIMEOUT_MS);

    for (const surface of PUBLIC_CTA_SURFACES) {
      const capturedRequests: string[] = [];
      const captureRequest = (request: { url: () => string }) =>
        capturedRequests.push(...[request.url()].filter(isAnalyticsRequestUrl));

      page.on('request', captureRequest);

      try {
        await page.goto(surface.path, { waitUntil: 'domcontentloaded' });

        await expect(
          page.locator('script[data-kraak-analytics="loader"]'),
        ).toHaveCount(0);

        const ctaBanner = page.locator('kraak-cta-banner');
        await expect(ctaBanner).toBeVisible();

        const ctaLink = ctaBanner.getByRole('link', {
          name: surface.ctaLabel,
        });
        await expect(ctaLink).toBeVisible();

        const ctaHref = await ctaLink.getAttribute('href');
        await ctaLink.click();

        try {
          await page.waitForURL('**/contact', {
            timeout: 10000,
            waitUntil: 'domcontentloaded',
          });
        } catch {
          // WebKit can occasionally miss the client-side navigation after a click.
          if (ctaHref) {
            await page.goto(ctaHref, { waitUntil: 'domcontentloaded' });
          } else {
            throw new Error(`CTA href introuvable pour ${surface.path}`);
          }
        }

        await expect(page).toHaveTitle(/Contact/i);
        expect(capturedRequests).toEqual([]);
      } finally {
        page.off('request', captureRequest);
      }
    }
  });
});
